//! Build script for the screensaver QEMU vertical: the aarch64 `virt` vertical
//! build, and on every target the desktop's screensaver record ids the
//! contract borrows (`contract.rs`), from their own definitions, so the guest
//! links none of the desktop.

use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    tairix_itest_harness::aarch64_virt_guest_build(1);

    let out_dir = env::var_os("OUT_DIR").expect("OUT_DIR set by cargo");
    let contract = format!(
        "// Auto-generated by build.rs. DO NOT EDIT.\n\
         /// The desktop's record of a saver it lists but will not run.\n\
         pub const SAVER_REFUSED: u32 = {refused};\n\
         /// The desktop's record of a hosted saver's first frame.\n\
         pub const SAVER_SHOWN: u32 = {shown};\n\
         /// The desktop's record of a hosted saver taken down on purpose.\n\
         pub const SAVER_DISMISSED: u32 = {dismissed};\n\
         /// The desktop's record of a hosted saver ended for misbehaving.\n\
         pub const SAVER_ENDED: u32 = {ended};\n\
         /// Why the desktop refuses a user's saver that asks for a feed.\n\
         pub const FEED_REFUSAL: &str = {feed:?};\n",
        feed =
            tairix_wallpaper::standing_reason(tairix_abi::window_ipc::SaverStanding::AsksForAFeed),
        refused = tairix_desktop_session::SAVER_REFUSED.0,
        shown = tairix_desktop_session::SAVER_SHOWN.0,
        dismissed = tairix_desktop_session::SAVER_DISMISSED.0,
        ended = tairix_desktop_session::SAVER_ENDED.0,
    );
    fs::write(PathBuf::from(&out_dir).join("contract.rs"), contract).expect("write contract.rs");
}
